using System;using System.Linq;using System.Windows.Forms;using System.Collections.Generic;using System.Drawing;
namespace LoopPedal {partial class Pedal {
 PerformanceTimeline Timeline{get{return loopers[0].Performance;}}PerformanceControl Port{get{return loopers[0].Controls;}}
 sealed class PerformanceKnob {public Knob Knob;public int Target;public long Audio;}readonly List<PerformanceKnob> performanceKnobs=new List<PerformanceKnob>();
 void RefreshPerformanceKnobs(){for(int i=performanceKnobs.Count-1;i>=0;i--){var binding=performanceKnobs[i];var knob=binding.Knob;if(knob.IsDisposed){performanceKnobs.RemoveAt(i);continue;}if(knob.Capture)continue;int value=knob.Min+(int)Math.Round(Port.get(binding.Target,binding.Audio)*(knob.Max-knob.Min));if(knob.Value!=value){knob.Value=value;knob.Invalidate();}}}
 bool PerformanceTarget(string key,out int target,out long audio){target=0;audio=0;if(key=="MASTER"){target=300;return true;}if(key.StartsWith("FX.")){bool b=key.StartsWith("FX.B.");int k;if(!int.TryParse(key.Substring(b?5:3),out k))return false;target=100+FxParameters.Canonical(k)+(b?100:0);return true;}var parts=key.Split('.');if(parts.Length!=4||parts[1]!="Layer")return false;int bank=parts[0]=="B"?1:0,slot;if(!int.TryParse(parts[2],out slot)||slot>=loopers[bank].Layers.Count)return false;int kind=Array.IndexOf(new[]{"STRETCH","PITCH","FILTER","LEVEL","PAN"},parts[3]);if(kind<0)return false;target=1000+bank*8+kind;audio=loopers[bank].Destructive?0:loopers[bank].Layers[slot].AudioId;return true;}
 void HookPerformance(string key,Knob knob){int target;long audio;if(!PerformanceTarget(key,out target,out audio))return;performanceKnobs.Add(new PerformanceKnob{Knob=knob,Target=target,Audio=audio});RegisterLfoTarget(knob,target,audio);var commit=knob.Commit;knob.Commit=v=>{if(Timeline.recording&&target>=1000&&(target-1000)%8<2)Port.Prepare(target,audio);lock(loopers[0].Gate)Timeline.touch(Port,target,audio,(v-knob.Min)/(float)(knob.Max-knob.Min));if(commit!=null)commit(v);};}
 string TargetLabel(int target,long audio){if(target==300)return "MASTER";if(target<1000)return (target>=200?"B · ":"FX · ")+(target%100>=36?AtmosFx.targetName(target%100):FxParameters.Name(target%100,loopers[0].Fx));var layer=Port.Layer(target,audio);return ((target-1000)/8==0?"A":"B")+" · "+(layer==null?"Missing layer":layer.Name)+" · "+new[]{"STRETCH","PITCH","FILTER","LEVEL","PAN"}[(target-1000)%8];}
 string LengthLabel(int mode,double length){return mode==4?"Start / Finish":mode<2?"Follow "+(mode==0?"A":"B"):length.ToString("0.##")+(mode==2?" beats":" sec");}
 void LengthItems(ToolStripItemCollection items,int mode,double value,Action<int,double> set){Item(items,"Start / Finish · free length",()=>set(4,value),mode==4);Item(items,"Follow A loop",()=>set(0,value),mode==0);Item(items,"Follow B loop",()=>set(1,value),mode==1);Item(items,"Tempo · beats…",()=>NumberMenu("Length in beats",(decimal)value,.125m,600,3,v=>set(2,(double)v)),mode==2);Item(items,"Free · seconds…",()=>NumberMenu("Length in seconds",(decimal)value,.02m,600,3,v=>set(3,(double)v)),mode==3);}
 void AutomationRecord(){lock(loopers[0].Gate){if(Timeline.recording||Timeline.armed)Timeline.stop();else Timeline.arm(Port,true);}}
 void AutomationPlay(){lock(loopers[0].Gate){Timeline.playing=!Timeline.playing;if(!Timeline.playing)for(int i=0;i<Timeline.count;i++)Port.set(Timeline.lanes[i].target,Timeline.lanes[i].audio,Timeline.lanes[i].baseline);}}
 void InstallAutomationTransport(Panel footer){var group=new FlowLayoutPanel{Name="AutomationButtons",AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,WrapContents=false,Margin=Padding.Empty,Padding=Padding.Empty};footer.Controls.Add(group);var record=(PadButton)Btn("● AUTO REC",AutomationRecord);record.Name="AutomationRecord";record.Size=new Size(146,30);record.Margin=new Padding(3,1,3,1);record.Accent=Skin.Gold;group.Controls.Add(record);RegisterMidi("Automation.Record",record);var playback=(PadButton)Btn("Ⅱ AUTO",AutomationPlay);playback.Name="AutomationPlayback";playback.Size=new Size(104,30);playback.Margin=record.Margin;group.Controls.Add(playback);RegisterMidi("Automation.Play",playback);InstallLfoTile(group);var options=Btn("⋯",()=>{var menu=NewMenu();PerformanceItems(menu.Items);menu.Show(group,new Point(0,0),ToolStripDropDownDirection.AboveRight);});options.Size=new Size(42,30);options.Margin=record.Margin;group.Controls.Add(options);var info=new Label{Name="AutomationInfo",Height=16,ForeColor=Skin.Muted,TextAlign=ContentAlignment.MiddleCenter,Margin=Padding.Empty};footer.Controls.Add(info);Action arrange=()=>{group.Location=new Point(Math.Max(0,(footer.ClientSize.Width-group.Width)/2),2);info.SetBounds(0,37,footer.ClientSize.Width,16);};footer.Resize+=(s,e)=>arrange();group.SizeChanged+=(s,e)=>arrange();arrange();timer.Tick+=(s,e)=>{record.Text=Timeline.recording?"■ FINISH "+((Timeline.time-Timeline.recordAt)/48000.0).ToString("0.0")+"s":Timeline.armed?"CANCEL · ARMED":"● AUTO REC";record.Lit=Timeline.recording||Timeline.armed;record.Accent=Timeline.recording?Skin.Red:Skin.Gold;record.Invalidate();playback.Text=Timeline.playing?"Ⅱ AUTO":"▶ AUTO";playback.Lit=Timeline.playing&&Timeline.count>0;playback.Invalidate();info.Text=Timeline.recording?"RECORDING":Timeline.armed?"NEXT LOOP":Timeline.count+" lanes · "+LengthLabel(Timeline.recordMode,Timeline.recordLength);};}

 void PerformanceItems(ToolStripItemCollection items){var automation=Item(items,"Automation");Item(automation.DropDownItems,Timeline.recording||Timeline.armed?"Finish recording":Timeline.recordMode==4?"Record knob movements · Start / Finish":"Record knob movements · next loop",AutomationRecord);var duration=Item(automation.DropDownItems,"Record length · "+LengthLabel(Timeline.recordMode,Timeline.recordLength));LengthItems(duration.DropDownItems,Timeline.recordMode,Timeline.recordLength,(m,v)=>{Timeline.recordMode=m;Timeline.recordLength=v;});Item(automation.DropDownItems,"Playback",AutomationPlay,Timeline.playing);
 for(int i=0;i<Timeline.count;i++){var l=Timeline.lanes[i];var lane=Item(automation.DropDownItems,TargetLabel(l.target,l.audio));Item(lane.DropDownItems,"Enabled",()=>{lock(loopers[0].Gate){l.enabled=!l.enabled;if(!l.enabled)Port.set(l.target,l.audio,l.baseline);}},l.enabled);var length=Item(lane.DropDownItems,"Length · "+(l.mode==4?(l.span/48000.0).ToString("0.00")+" sec · free":LengthLabel(l.mode,l.length)));LengthItems(length.DropDownItems,l.mode,l.length,(m,v)=>{lock(loopers[0].Gate){l.mode=m;l.length=v;l.phaseOffset=0;}});Item(lane.DropDownItems,"Delete lane",()=>{lock(loopers[0].Gate){Port.set(l.target,l.audio,l.baseline);int at=Array.IndexOf(Timeline.lanes,l);Array.Copy(Timeline.lanes,at+1,Timeline.lanes,at,Timeline.count-at-1);Timeline.lanes[--Timeline.count]=null;}});}
 Item(automation.DropDownItems,"Clear automation and modulation",()=>{if(MessageBox.Show(this,"Clear automation and modulation?","Agent Looper",MessageBoxButtons.OKCancel)==DialogResult.OK)lock(loopers[0].Gate)Timeline.clear(Port);});var modulation=Item(items,"Modulation");for(int slot=0;slot<4;slot++){var mod=Timeline.mods[slot];var entry=Item(modulation.DropDownItems,(slot+1)+" · "+(mod.target<0?"Unassigned":TargetLabel(mod.target,mod.audio)));Item(entry.DropDownItems,"LFO settings…",()=>{selectedLfo=Array.IndexOf(Timeline.mods,mod);ShowLfoSettings();});var target=Item(entry.DropDownItems,"Target");TargetItems(target.DropDownItems,(id,audio)=>{AssignLfo(Array.IndexOf(Timeline.mods,mod),id,audio);});Item(entry.DropDownItems,"Enabled",()=>{lock(loopers[0].Gate){mod.enabled=!mod.enabled;if(!mod.enabled)Timeline.restore(Port,mod);}},mod.enabled);var shape=Item(entry.DropDownItems,"Shape");for(int k=0;k<LfoMath.TYPES.Length;k++){int type=k;Item(shape.DropDownItems,LfoMath.TYPES[k],()=>{mod.type=type;if(type==2)mod.polarity=1;},mod.type==k);}Item(entry.DropDownItems,"Depth · "+(mod.depth*100).ToString("0")+"%",()=>NumberMenu("Modulation depth %",(decimal)(mod.depth*100),0,100,1,v=>mod.depth=(double)v/100));var rate=Item(entry.DropDownItems,"Rate · "+LengthLabel(mod.mode,mod.rate));Item(rate.DropDownItems,"Tempo · beats…",()=>NumberMenu("Beats per cycle",(decimal)mod.rate,.02m,600,3,v=>{mod.mode=2;mod.rate=(double)v;}));Item(rate.DropDownItems,"Free · seconds…",()=>NumberMenu("Seconds per cycle",(decimal)mod.rate,.02m,600,3,v=>{mod.mode=3;mod.rate=(double)v;}));}SceneItems(Item(items,"Scenes").DropDownItems);}
 void TargetItems(ToolStripItemCollection items,Action<int,long> set){Item(items,"MASTER",()=>set(300,0));var fx=Item(items,"Effects");for(int k=0;k<48;k++){if(FxParameters.Canonical(k)!=k)continue;int id=100+k;Item(fx.DropDownItems,TargetLabel(id,0),()=>set(id,0));}foreach(int k in new[]{0,2,5,18}){int id=200+k;Item(fx.DropDownItems,TargetLabel(id,0),()=>set(id,0));}for(int bank=0;bank<2;bank++){int b=bank;var group=Item(items,b==0?"Looper A":"Looper B");foreach(var l in loopers[b].Layers){long audio=loopers[b].Destructive?0:l.AudioId;var layer=Item(group.DropDownItems,l.Name);for(int k=0;k<5;k++){int target=1000+b*8+k;Item(layer.DropDownItems,new[]{"STRETCH","PITCH","FILTER","LEVEL","PAN"}[k],()=>set(target,audio));}}}}
 void SceneItems(ToolStripItemCollection items){for(int i=0;i<8;i++){int slot=i;var scene=Item(items,loopers[0].Scenes.Names[i]+(loopers[0].Scenes.Slots[i]==null?" · Empty":""));Item(scene.DropDownItems,"Recall · next A loop",()=>RecallScene(slot,true));Item(scene.DropDownItems,"Recall now",()=>RecallScene(slot,false));Item(scene.DropDownItems,"Capture current state",()=>{EnsureNotRecording();loopers[0].Scenes.Slots[slot]=PerformanceScene.Capture(loopers);status.Text="Scene captured";});Item(scene.DropDownItems,"Rename…",()=>SceneName(slot));Item(scene.DropDownItems,"Delete",()=>loopers[0].Scenes.Slots[slot]=null);}}
 void SceneName(int slot){using(var form=new Form{Text="Scene name",Size=new Size(330,150),FormBorderStyle=FormBorderStyle.FixedToolWindow,StartPosition=FormStartPosition.CenterParent,BackColor=Skin.Ink,ForeColor=Color.WhiteSmoke,ShowInTaskbar=false}){var text=new TextBox{Text=loopers[0].Scenes.Names[slot],Location=new Point(16,16),Width=280,MaxLength=64,BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke};form.Controls.Add(text);var save=Btn("SAVE",()=>form.DialogResult=DialogResult.OK);save.SetBounds(196,55,100,34);form.Controls.Add(save);form.AcceptButton=save;if(form.ShowDialog(this)==DialogResult.OK&&!string.IsNullOrWhiteSpace(text.Text))loopers[0].Scenes.Names[slot]=text.Text.Trim();}}
 void SyncProjectUi(){var b=loopers[0];tempoSetting.Value=Math.Max(tempoSetting.Minimum,Math.Min(tempoSetting.Maximum,(decimal)b.BPM));int meter=meterSetting.Items.IndexOf(b.BeatsPerBar+"/"+b.BeatUnit);if(meter>=0)meterSetting.SelectedIndex=meter;countSetting.SelectedIndex=b.CountInBars;SetSingleMode(b.SingleLooper);if(syncFxBanks!=null)syncFxBanks();RefreshTracks();}
 void EnsureNotRecording(){if(loopers.Any(b=>b.Recording))throw new Exception("Finish recording first.");}
 async void RecallScene(int slot,bool quantized){try{EnsureNotRecording();var scene=loopers[0].Scenes.Slots[slot];if(scene==null)return;status.Text="Preparing scene…";var ready=await System.Threading.Tasks.Task.Run(()=>scene.Prepare());EnsureNotRecording();var retiring=PerformanceScene.Capture(loopers).Banks;retiring[0].Partner=retiring[1];retiring[1].ClockLeader=retiring[0];var oldProvider=new LoopProvider(retiring[0]);lock(loopers[0].Gate){var store=loopers[0].Scenes;long cycle=Port.cycle(0),phase=Port.phase(0);store.At=loopers[0].AudioFrame+(quantized&&loopers[0].Playing?(cycle-(phase%cycle+cycle)%cycle)%cycle:0);store.Retiring=retiring;store.RetiringProvider=oldProvider;store.RetireOwner=loopers[0];store.Pending=ready;store.Queued=slot;}status.Text="Scene queued";}catch(Exception ex){status.Text=ex.Message;}}
}}
